<template>
  <div class="goodsListNav">
    <div id="left" class="left">
      <span 
        class="leftItem" 
        :id="index + 'b'" 
        @click="setIsAction(item, index)"
        :style="isAction === index ? leftAction : ''" 
        v-for="(item, index) in list" 
        :key="index"
      >
        {{ item.name }}
      </span>
    </div>
    <div id="right">
      <div 
        :id="index + 'a'" 
        class="item" 
        v-for="(item, index) in list" 
        :key="index"
      >
        <p class="shop-title">
          {{ item.name }}
        </p>
        <div 
          class="items" 
          v-for="(items, i) in item.itemList" 
          :key="i"
          @click="addCar(items)"
        >
          <div class="items-left">
            <img :src="items.itemImg" alt="" />
          </div>
          <div class="items-right">
            <h4>{{ items.itemName }}</h4>
            <p>
              <span v-for="(info, idx) in items.itemInfo" :key="idx">{{ info }}</span>
            </p>
            <div>
              <p>¥{{ items.price }}</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: "list",
  props: {
    list: {
      type: Array,
      default: []
    }
  },
  data() {
    return {
      isAction: 0,
      isBottom: false,
      bottomNum: null,
      // 选中项改为深蓝色主题
      leftAction: {
        background: "#165DFF",
        color: "#ffffff",
        fontWeight: "bold"
      }
    };
  },
  mounted() {
    this.init();
  },
  methods: {
    init() {
      const dom = document.getElementById("right");
      const domLeft = document.getElementById("left");
      dom.addEventListener("scroll", (res) => {
        if (this.isBottom) {
          this.isAction = this.bottomNum;
          this.bottomNum = null;
          this.isBottom = false;
        }
        const topDom = document.getElementById(this.isAction + "a");
        const leftItem = document.getElementById(this.isAction + "b");
        if (dom.scrollTop > topDom.scrollHeight + topDom.offsetTop) {
          this.isAction = this.isAction + 1;
        } else if (dom.scrollTop + 1 < topDom.offsetTop && this.isAction !== 0) {
          this.isAction = this.isAction - 1;
        } else if (dom.scrollHeight <= Math.ceil(dom.scrollTop + dom.offsetHeight)) {
          this.bottomNum = this.isAction;
          this.isAction = this.list.length - 1;
          this.isBottom = true;
          domLeft.scrollTo({
            top: domLeft.scrollHeight - domLeft.clientHeight
          });
        }
        if (domLeft.clientHeight + domLeft.scrollTop < leftItem.scrollHeight + leftItem.offsetTop) {
          domLeft.scrollTo({
            top: domLeft.scrollTop + leftItem.scrollHeight
          });
        } else if (domLeft.scrollTop > leftItem.offsetTop) {
          domLeft.scrollTo({
            top: domLeft.scrollTop - leftItem.scrollHeight
          });
        }
      });
    },
    setIsAction(item, index) {
      this.isAction = index;
      const dom = document.getElementById("right");
      const topDom = document.getElementById(this.isAction + "a");
      dom.scrollTo({
        top: topDom.offsetTop
      });
    },
    addCar(e) {
      this.$emit("newCarNum", e);
    }
  }
};
</script>

<style scoped>
/* 全局容器 */
.goodsListNav {
  height: 70vh;
  width: 100vw;
  position: relative;
}

/* 左侧分类栏 底色改为浅蓝灰 贴合主题 */
.goodsListNav .left {
  position: absolute;
  top: 0;
  left: 0;
  width: 25vw;
  height: 100%;
  display: flex;
  flex-direction: column;
  overflow: scroll;
  background: #f0f5fc;
}

/* 左侧未选中分类样式 */
.goodsListNav .left .leftItem {
  cursor: pointer;
  padding: 10px;
  text-align: center;
  border-right: 2px solid transparent;
  color: #333;
}

/* 右侧商品区域 */
#right {
  width: 75vw;
  padding-left: 25vw;
  height: 100%;
  overflow: scroll;
  background-color: #f7f9fc;
}

#right .item {
  padding: 0 0 10px;
}

#right .items {
  padding: 5px 0;
}

/* 分类标题栏 深蓝下划线 */
.shop-title {
  line-height: 30px;
  font-size: 12px;
  margin: 0;
  padding: 0 0 10px;
  border-bottom: 2px solid #165DFF;
  box-shadow: 0 2px 2px rgba(22, 93, 255, 0.08);
  color: #165DFF;
  font-weight: bold;
}

.items {
  display: flex;
  border-bottom: 1px solid #e6edf8;
  margin: 2px 0;
  background: #fff;
  border-radius: 6px;
}

.items * {
  margin: 0;
  padding: 0;
}

.items-left {
  width: 40%;
  box-sizing: border-box;
  padding: 14px;
}

.items-left img {
  display: block;
  width: 100%;
  height: 100%;
  border-radius: 8px;
}

.items-right {
  width: 60%;
  padding-left: 5px;
  position: relative;
}

.items-right>h4 {
  font-size: 20px;
  font-weight: normal;
  color: #1d2129;
}

.items-right>p {
  margin: 4px 0;
  font-size: 13px;
  color: #777;
}

/* 标签边框改为深蓝色 */
.items-right>p>span {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 10px;
  border: 1px solid #165DFF;
  color: #165DFF;
  margin-right: 5px;
}

.items-right>div {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
}

/* 价格颜色保留醒目，加货币符号更规范 */
.items-right>div>p {
  font-size: 18px;
  color: #E53E3E;
  font-weight: bold;
}
</style>



