import Vue from 'vue'
import Vuex from "vuex";

Vue.use(Vuex)

const state = {
  // 购物车商品列表
  tableData: [],
  // 满减规则：满30减5 / 满50减12 / 满80减20
  fullReduceRules: [
    { full: 30, reduce: 5 },
    { full: 50, reduce: 12 },
    { full: 80, reduce: 20 }
  ]
}

// 操作state数据
const mutations = {
  // 增加订单
  addTableData(state, n) {
    // 检查商品是否已存在，如果存在则增加数量
    const existItem = state.tableData.find(item => item.name === n.name)
    if (existItem) {
      existItem.num += 1
    } else {
      state.tableData.push({
        name: n.name,
        num: 1,
        price: n.price
      })
    }
  },
  // 删除订单
  deleteTableData(state, index) {
    state.tableData.splice(index, 1)
  },
  // 清空订单
  clearTableData(state) {
    state.tableData = []
  }
}

// 新增getters：计算原价、减免金额、实付金额
const getters = {
  // 商品总原价
  totalOriginalPrice(state) {
    return state.tableData.reduce((sum, item) => sum + item.price * item.num, 0)
  },
  // 计算满减抵扣金额
  reducePrice(state, getters) {
    const total = getters.totalOriginalPrice
    let reduce = 0
    if (total >= 80) {
      reduce = 20
    } else if (total >= 50) {
      reduce = 12
    } else if (total >= 30) {
      reduce = 5
    }
    return reduce
  },
  // 最终实付价格
  realPayPrice(state, getters) {
    return (getters.totalOriginalPrice - getters.reducePrice).toFixed(2)
  },
  // 商品总件数
  totalCount(state) {
    return state.tableData.reduce((sum, item) => sum + item.num, 0)
  }
}

export default new Vuex.Store({
  state,
  mutations,
  getters // 挂载计算属性
})



