
<template>
  <div class="tabbar">
    <ul>
      <li 
        @click="go(item.path)" 
        :class="{ active: message === item.path }" 
        v-for="(item, index) in atabs" 
        :key="index"
      >
        <img :src="message === item.path ? item.icon_active : item.icon" />
        {{ item.title }}
      </li>
    </ul>
  </div>
</template>

<script>
export default {
  name: "tabbar",
  props: {
    selected: String,
  },
  data() {
    return {
      message: this.selected,
      atabs: [
        {
          title: "点餐",
          path: "/",
          icon: require("@/assets/images/index.png"),
          icon_active: require("@/assets/images/index-active.png"),
        },
        {
          title: "订单",
          path: "/order",
          icon: require("@/assets/images/order.png"),
          icon_active: require("@/assets/images/order-active.png"),
        },
      ],
    };
  },
  methods: {
    go(url) {
      this.$router.push(url);
    },
  },
};
</script>
<style scoped>
.tabbar {
  position: fixed; /* 固定定位 */
  left: 0;
  right: 0;
  bottom: 0;
  height: 10vh;
  z-index: 999;
}

.tabbar ul {
  width: 100%;
  height: 10vh;
  display: flex;
  align-items: center;
  background-color: #fff;
  list-style: none;
  padding: 0;
  margin: 0;
  border-top: 1px solid #eaeaea;
}

.tabbar li {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  flex: 1;
  font-size: 13px;
}

.tabbar img {
  width: 20px;
  height: 20px;
  display: block;
}

.tabbar li.active {
  color: #165DFF;
  font-weight: bold;
}
</style>



