<template>
  <div>
    <div class="car-btn" @click="goOrder(btnPath)">
      <span class="badge" v-if="carCount > 0">{{ carCount }}</span>
      <img :src="btnImg" alt="购物车" />
      <!-- 悬浮小提示：满减优惠 -->
      <div class="reduce-tip" v-if="carCount > 0">结算享满减 ¥</div>
    </div>
  </div>
</template>

<script>
export default {
  name: 'carBtn',
  data() {
    return {
      btnImg: require("@/assets/images/shopping-cart.png"),
      btnPath: '/order'
    };
  },
  computed: {
    carCount() {
      // 计算购物车中商品总数量
      return this.$store.state.tableData.reduce((total, item) => total + item.num, 0);
    }
  },
  methods: {
    goOrder(path) {
      this.$router.push(path); // 路由跳转到订单结算页查看满减
    }
  }
};
</script>

<style scoped>
.car-btn {
  width: 52px;
  height: 52px;
  position: fixed;
  right: 6vw;
  bottom: 12vh;
  border-radius: 50%;
  background: linear-gradient(135deg, #165DFF 0%, #2e7fff 100%);
  box-shadow: 0 4px 14px rgba(22, 93, 255, 0.4);
  display: flex;
  justify-content: center;
  align-items: center;
  cursor: pointer;
  transition: all 0.2s ease;
  z-index: 100;
}
.car-btn:active {
  transform: scale(0.92);
}
.car-btn img {
  width: 26px;
  height: 26px;
  filter: brightness(10);
}

/* 数量角标 */
.badge {
  background: #ff4d4f;
  color: #fff;
  position: absolute;
  min-width: 18px;
  height: 18px;
  border-radius: 9px;
  font-size: 12px;
  text-align: center;
  line-height: 18px;
  top: -4px;
  right: -4px;
  padding: 0 4px;
  border: 2px solid #fff;
}

/* 满减悬浮提示文字 */
.reduce-tip {
  position: absolute;
  right: 58px;
  background: #fa8c16;
  color: #fff;
  font-size: 11px;
  padding: 3px 8px;
  border-radius: 12px;
  white-space: nowrap;
  box-shadow: 0 2px 6px rgba(250, 140, 22, 0.4);
}
</style>



