<template>
  <div>
    <user-head></user-head>
    <list :list="list" @newCarNum="carList"></list>
    <car-btn></car-btn>
    <tab-bar :selected="selected"></tab-bar>
  </div>
</template>

<script>
import TabBar from "@/components/tabbar.vue";
import List from "@/pages/index/common/list.vue";
import UserHead from "@/pages/index/common/userHeader.vue";
import CarBtn from "@/pages/index/common/carBtn.vue";

export default {
  name: "index",
  data() {
    return {
      selected: "/",
      list: [
        {
          name: "招牌奶茶",
          id: 0,
          itemList: [
            {
              itemName: "经典珍珠奶茶",
              itemInfo: ["红茶底", "Q弹黑珍珠"],
              price: 12,
              itemImg: "static/images/milk01.svg"
            },
            {
              itemName: "芋泥波波奶茶",
              itemInfo: ["手工芋泥", "温热推荐"],
              price: 15,
              itemImg: "static/images/milk02.svg"
            },
            {
              itemName: "焦糖烤奶",
              itemInfo: ["焦香风味", "少糖更佳"],
              price: 13,
              itemImg: "static/images/milk03.svg"
            },
            {
              itemName: "可可巧克力奶茶",
              itemInfo: ["浓郁可可", "冬日热饮"],
              price: 16,
              itemImg: "static/images/milk04.svg"
            }
          ]
        },
        {
          name: "鲜果茶",
          id: 1,
          itemList: [
            {
              itemName: "手打柠檬红茶",
              itemInfo: ["暴打香水柠檬", "清爽解腻"],
              price: 11,
              itemImg: "static/images/fruit01.svg"
            },
            {
              itemName: "满杯百香果",
              itemInfo: ["双份果肉", "酸甜浓郁"],
              price: 14,
              itemImg: "static/images/fruit02.svg"
            },
            {
              itemName: "西瓜气泡茶",
              itemInfo: ["夏日限定", "气泡口感"],
              price: 16,
              itemImg: "static/images/fruit03.svg"
            },
            {
              itemName: "蜜桃乌龙鲜果茶",
              itemInfo: ["白桃果肉", "乌龙茶底"],
              price: 15,
              itemImg: "static/images/fruit04.svg"
            }
          ]
        },
        {
          name: "甜品小食",
          id: 2,
          itemList: [
            {
              itemName: "焦糖鲜奶布丁",
              itemInfo: ["嫩滑口感", "饭后甜品"],
              price: 8,
              itemImg: "static/images/dessert01.svg"
            },
            {
              itemName: "迷你提拉米苏杯",
              itemInfo: ["意式经典", "微苦不腻"],
              price: 18,
              itemImg: "static/images/dessert02.svg"
            },
            {
              itemName: "流心芝士蛋挞2个",
              itemInfo: ["趁热食用", "芝士内馅"],
              price: 9,
              itemImg: "static/images/dessert03.svg"
            },
            {
              itemName: "抹茶大福2枚",
              itemInfo: ["软糯外皮", "奶油内馅"],
              price: 12,
              itemImg: "static/images/dessert04.svg"
            }
          ]
        }
      ]
    };
  },
  components: {
    TabBar,
    List,
    UserHead,
    CarBtn
  },
  methods: {
    carList(d) {
      // 将商品添加到 Vuex store 中
      this.$store.commit('addTableData', {
        name: d.itemName,
        price: d.price
      });
      alert("已加入购物车，可以去结算享受满减优惠啦");
    }
  }
};
</script>



