
<template>
  <div class="order-page">
    <h4 class="title">我的订单</h4>

    <div v-if="tableData.length !== 0" class="order-content">
      <table cellspacing="0" class="orderTable">
        <tr class="tabTop">
          <th>序号</th>
          <th>名称</th>
          <th>单价</th>
          <th>数量</th>
          <th>小计</th>
          <th>操作</th>
        </tr>
        <tr class="items-row" v-for="(item, index) in tableData" :key="index">
          <td>{{ index + 1 }}</td>
          <td class="name-cell">{{ item.name }}</td>
          <td>¥{{ item.price.toFixed(2) }}</td>
          <td>
            <span class="num-ctrl" @click="changeNum(index, -1)">−</span>
            {{ item.num }}
            <span class="num-ctrl" @click="changeNum(index, 1)">+</span>
          </td>
          <td class="subtotal">¥{{ (item.price * item.num).toFixed(2) }}</td>
          <td>
            <button class="btn-del" @click="deleteBtn(index)">删除</button>
          </td>
        </tr>
      </table>

      <!-- 结账金额明细面板：核心改造，清晰展示要付多少钱 -->
      <div class="bill-panel">
        <div class="bill-title">💰 结账金额明细</div>
        <div class="bill-row">
          <span>商品原价合计</span>
          <span>¥{{ totalOriginalPrice.toFixed(2) }}</span>
        </div>
        <div class="bill-row discount" v-if="reducePrice > 0">
          <span>满减优惠</span>
          <span class="discount-amount">- ¥{{ reducePrice.toFixed(2) }}</span>
        </div>
        <div class="discount-hint" v-if="nextReduce">
          💡 再加 ¥{{ nextReduce.diff.toFixed(2) }} 可减 {{ nextReduce.reduce }} 元
        </div>
        <div class="bill-total">
          <span>实付金额（需付款）</span>
          <span class="pay-amount">¥{{ realPayPrice }}</span>
        </div>
      </div>

      <div class="pay-bar">
        <div class="pay-bar-left">
          <span class="pay-label">合计应付：</span>
          <span class="pay-bar-price">¥{{ realPayPrice }}</span>
        </div>
        <button class="btn-pay" @click="payBtn">去结账</button>
      </div>
    </div>

    <div v-else class="noOrder">
      <div class="noOrder-icon">🛒</div>
      <p>购物车空空如也，快去点杯奶茶吧～</p>
      <button class="btn-go-order" @click="goHome">去点单</button>
    </div>

    <tab-bar :selected="selected"></tab-bar>
  </div>
</template>

<script>
import TabBar from '@/components/tabbar.vue';

export default {
  name: 'order',
  components: {
    TabBar
  },
  data() {
    return {
      selected: '/order'
    };
  },
  computed: {
    tableData() {
      return this.$store.state.tableData;
    },
    totalOriginalPrice() {
      return this.$store.getters.totalOriginalPrice;
    },
    reducePrice() {
      return this.$store.getters.reducePrice;
    },
    realPayPrice() {
      return this.$store.getters.realPayPrice;
    },
    // 提示下一档满减还差多少
    nextReduce() {
      const total = this.totalOriginalPrice;
      const rules = this.$store.state.fullReduceRules;
      for (let i = 0; i < rules.length; i++) {
        if (total < rules[i].full) {
          return { diff: rules[i].full - total, reduce: rules[i].reduce };
        }
      }
      return null;
    }
  },
  methods: {
    changeNum(index, delta) {
      const item = this.tableData[index];
      const newNum = item.num + delta;
      if (newNum <= 0) {
        if (confirm('数量减为 0，是否移除该商品？')) {
          this.$store.commit('deleteTableData', index);
        }
        return;
      }
      item.num = newNum;
    },
    payBtn() {
      const pay = this.realPayPrice;
      alert('🎉 下单成功！\n\n应付金额：¥' + pay +
            (this.reducePrice > 0 ? '\n已享满减优惠：-¥' + this.reducePrice.toFixed(2) : '') +
            '\n\n老板火速打包中，预计 3 秒送达～');
      this.$store.commit('clearTableData');
    },
    deleteBtn(n) {
      if (confirm('确定要删除「' + this.tableData[n].name + '」吗？')) {
        this.$store.commit('deleteTableData', n);
      }
    },
    goHome() {
      this.$router.push('/');
    }
  }
};
</script>

<style scoped>
.order-page {
  min-height: 100vh;
  background: #f7f9fc;
  padding-bottom: 130px;
}

.title {
  height: 6vh;
  min-height: 48px;
  background: linear-gradient(135deg, #165DFF 0%, #2e7fff 100%);
  line-height: 6vh;
  margin: 0;
  padding: 0;
  text-align: center;
  color: #fff;
  font-size: 17px;
  font-weight: bold;
}

.order-content {
  padding: 12px;
}

.orderTable {
  width: 100%;
  text-align: center;
  border-collapse: collapse;
  background: #fff;
  border-radius: 10px;
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(22,93,255,0.08);
}

.orderTable th {
  background: #f0f5fc;
  color: #165DFF;
  padding: 10px 4px;
  font-size: 13px;
  border-bottom: 2px solid #165DFF;
}

.orderTable td {
  padding: 10px 4px;
  font-size: 13px;
  border-bottom: 1px solid #eef2f9;
}

.name-cell {
  text-align: left;
  color: #1d2129;
  font-weight: 500;
}

.subtotal {
  color: #E53E3E;
  font-weight: bold;
}

.num-ctrl {
  display: inline-block;
  width: 22px;
  height: 22px;
  line-height: 20px;
  text-align: center;
  border-radius: 50%;
  background: #165DFF;
  color: #fff;
  font-size: 15px;
  cursor: pointer;
  user-select: none;
  margin: 0 3px;
}

.btn-del {
  color: #fff;
  border: none;
  padding: 4px 10px;
  cursor: pointer;
  border-radius: 4px;
  background: #ff5621;
  font-size: 12px;
}

/* ===== 结账金额明细面板 ===== */
.bill-panel {
  margin-top: 14px;
  background: #fff;
  border-radius: 10px;
  padding: 14px 16px;
  box-shadow: 0 2px 8px rgba(22,93,255,0.08);
  border-left: 4px solid #165DFF;
}

.bill-title {
  font-size: 15px;
  font-weight: bold;
  color: #165DFF;
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 1px dashed #e6edf8;
}

.bill-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 6px 0;
  font-size: 14px;
  color: #555;
}

.bill-row.discount {
  color: #E53E3E;
}

.discount-amount {
  font-weight: bold;
  color: #E53E3E;
}

.discount-hint {
  color: #fa8c16;
  font-size: 12px;
  background: #fff7e6;
  padding: 8px 10px;
  border-radius: 6px;
  margin-top: 6px;
}

.bill-total {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 10px;
  padding-top: 12px;
  border-top: 2px solid #f0f5fc;
  font-size: 16px;
  font-weight: bold;
  color: #1d2129;
}

.pay-amount {
  color: #E53E3E;
  font-size: 22px;
  font-weight: bold;
}

/* ===== 底部付款栏 ===== */
.pay-bar {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 10vh;
  height: 56px;
  background: #fff;
  border-top: 1px solid #eee;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 16px;
  box-shadow: 0 -2px 8px rgba(0,0,0,0.06);
  z-index: 99;
}

.pay-bar-left {
  display: flex;
  align-items: center;
}

.pay-label {
  font-size: 14px;
  color: #666;
}

.pay-bar-price {
  font-size: 22px;
  font-weight: bold;
  color: #E53E3E;
  margin-left: 6px;
}

.btn-pay {
  background: linear-gradient(135deg, #165DFF 0%, #2e7fff 100%);
  color: #fff;
  border: none;
  padding: 10px 28px;
  border-radius: 22px;
  font-size: 15px;
  font-weight: bold;
  cursor: pointer;
  box-shadow: 0 3px 10px rgba(22,93,255,0.3);
}

/* ===== 空状态 ===== */
.noOrder {
  text-align: center;
  margin-top: 80px;
  color: #999;
}

.noOrder-icon {
  font-size: 56px;
  margin-bottom: 12px;
}

.noOrder p {
  margin-bottom: 20px;
  font-size: 14px;
}

.btn-go-order {
  background: #165DFF;
  color: #fff;
  border: none;
  padding: 10px 30px;
  border-radius: 20px;
  cursor: pointer;
  font-size: 14px;
}
</style>



